#pragma once
static const char piko_keymap_html[] =
"<!doctype html>\n"
"<html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n"
"<title>PIKO Key Mapper v3</title>\n"
"<style>\n"
"body{background:#101722;color:#e9eff7;font:15px system-ui;margin:0}main{max-width:1100px;margin:20px auto;padding:18px}a{color:#71caff}button,input{font:inherit;padding:9px;border:1px solid #64758b;border-radius:7px;background:#22354b;color:white}button{cursor:pointer}button:disabled{opacity:.5}button.primary{background:#146a9c}table{width:100%;border-collapse:collapse;background:#1b2636}th,td{padding:10px;border-bottom:1px solid #3a4b62;text-align:left;vertical-align:top}input{width:90%;box-sizing:border-box}pre{white-space:pre-wrap;background:#070e19;padding:12px;border-radius:9px;max-height:50vh;overflow:auto}.notice{padding:14px;background:#263b52;border-radius:9px;margin:12px 0}.warn{color:#ffc875}\n"
"</style>\n"
"<main><a href=\"/#diag\">← Diag</a><h1>Physical key mapper · 6 × 3 serial scan</h1>\n"
"<p>For each key: <b>Start (no key held)</b> → hold the physical key and click <b>Capture held</b> while still pressing it → release it and click <b>Save released</b>. This compares baseline / pressed / released and counts GPIO32/33/34 rising interrupts by selector index. A single interrupt row is a candidate, not proof of physical wiring.</p>\n"
"<div id=\"status\" class=\"notice\">Ready</div>\n"
"<table><thead><tr><th>Physical key</th><th>Measured GPIO and matrix differences</th><th>Action</th></tr></thead><tbody id=\"body\"></tbody></table>\n"
"<p><button id=\"add\">Add row</button> <button id=\"report\" class=\"primary\">Generate report & copy</button> <button id=\"clear\">Clear mapping</button></p>\n"
"<pre id=\"output\">No report yet.</pre>\n"
"<script>\n"
"const cols=[32,33,34],tbody=document.querySelector('#body');let active=-1,phase=0;\n"
"let records;try{records=JSON.parse(localStorage.getItem('piko-keymap-v6')||'null')}catch(e){}if(!Array.isArray(records))records=Array.from({length:16},(_,i)=>({key:i<10?String(i):i===10?'STOP':i===11?'Rotary press':i===12?'Rotary left':i===13?'Rotary right':'',data:null,held:null}));\n"
"function persist(){localStorage.setItem('piko-keymap-v6',JSON.stringify(records))}\n"
"function bitdiff(a,b){return (a^b)>>>0}\n"
"function snapshot(d){return {raw:d.currentRaw,idle:d.currentIdle,rows:d.currentRows,pins:d.currentPins,rotary:d.rotaryDelta,samples:d.samples}}\n"
"function format(d,h){\n"
" if(!d||!h)return 'Not scanned';\n"
" const out=[],pins=['GPIO2','GPIO15','GPIO12','GPIO13'],selected=((h.raw>>>0)^(d.baseRaw>>>0))>>>0;\n"
" for(let i=0;i<18;i++)if(selected&(1<<i))out.push('SELECTED shift bit'+Math.floor(i/3)+' → GPIO'+cols[i%3]);\n"
" const idleDelta=(d.baseIdle||0)^(h.idle||0);\n"
" if(!selected && idleDelta)out.push('UNRESOLVED: GPIO column changes even with no shift row selected');\n"
" if(!selected && !idleDelta)out.push('NO SELECTED ROW DETECTED');\n"
" if(idleDelta)out.push('Idle GPIO columns '+d.baseIdle+'→'+h.idle);\n"
" const pressed=h.rows||Array(6).fill(0),baseline=d.baseRows||Array(6).fill(0);\n"
" let common=7;for(let r=0;r<6;r++)common &= (pressed[r]^baseline[r]);\n"
" if(common)out.push('All 6 sampled rows change together on '+cols.filter((_,i)=>common&(1<<i)).map(g=>'GPIO'+g).join(', ')+' (NOT a row ID)');\n"
" for(let i=0;i<4;i++)if(((d.basePins^h.pins)&(1<<i))!==0)out.push('Held '+pins[i]+' '+((d.basePins>>i)&1)+'→'+((h.pins>>i)&1));\n"
" if(h.rotary)out.push('Rotary held delta '+h.rotary);\n"
" if(d.rotaryDelta!==h.rotary)out.push('Rotary final delta '+d.rotaryDelta);\n"
" const n=d.rawTransitions||[],pp=d.pinTransitions||[],edges=[];\n"
" for(let i=0;i<18;i++)if(n[i])edges.push('shift'+Math.floor(i/3)+'/GPIO'+cols[i%3]+':'+n[i]);\n"
" for(let i=0;i<4;i++)if(pp[i])edges.push(pins[i]+':'+pp[i]);\n"
" out.push('Edges ['+(edges.join(' ')||'none')+']');\n"
" const isr=d.irqEdges||[], unassigned=d.irqUnassigned||[0,0,0], hits=[];\n"
" let irqTotal=0;\n"
" for(let i=0;i<18;i++)if(isr[i]){hits.push('shift'+Math.floor(i/3)+'/GPIO'+cols[i%3]+':'+isr[i]);irqTotal+=isr[i];}\n"
" out.push('IRQ edges by selector ['+(hits.join(' ')||'none')+']');\n"
" if(unassigned.some(x=>x))out.push('IRQ edges outside a selected row ['+unassigned.join(',')+']');\n"
" if(!irqTotal)out.push('No GPIO rising interrupts captured (cannot infer row)');\n"
" if((pp[2]||0)>20)out.push('GPIO12 noisy ('+pp[2]+' edges; ignore for key identification)');\n"
" const released=d.currentRows||Array(6).fill(0);\n"
" if(d.currentRaw!==d.baseRaw || d.currentIdle!==d.baseIdle || released.some((x,i)=>x!==baseline[i]))out.push('WARN: keyboard columns did not return to baseline');\n"
" return out.join('; ')+' (samples '+d.samples+')';\n"
"}\n"
"function render(){tbody.replaceChildren();records.forEach((r,i)=>{const tr=document.createElement('tr'),key=document.createElement('td'),val=document.createElement('td'),act=document.createElement('td'),input=document.createElement('input'),b=document.createElement('button');input.value=r.key;input.placeholder='Button name';input.oninput=()=>{r.key=input.value;persist()};key.append(input);val.textContent=r.data&&r.held?format(r.data,r.held):'Not scanned';\n"
"b.textContent=active===i?(phase===1?'Capture held (keep key pressed)':'Save released (release key first)'):'Start scan (no key pressed)';\n"
"b.disabled=active!==-1&&active!==i;b.className='primary';b.onclick=()=>scan(i);act.append(b);tr.append(key,val,act);tbody.append(tr)})}\n"
"async function scan(i){try{const status=document.querySelector('#status');if(active===-1){const r=await fetch('/api/capture/start',{method:'POST'});if(!r.ok)throw Error('Start HTTP '+r.status);active=i;phase=1;status.textContent='Now press and HOLD \"'+records[i].key+'\", then click Capture held while pressing.'}\n"
"else if(active===i&&phase===1){const r=await fetch('/api/capture',{cache:'no-store'});if(!r.ok)throw Error('Capture HTTP '+r.status);records[i].held=snapshot(await r.json());phase=2;status.textContent='Held state captured. RELEASE \"'+records[i].key+'\", then click Save released.'}\n"
"else if(active===i&&phase===2){const r=await fetch('/api/capture/stop',{method:'POST'});if(!r.ok)throw Error('Stop HTTP '+r.status);records[i].data=await r.json();active=-1;phase=0;persist();status.textContent='Saved '+records[i].key+'; start next row.'}render()}catch(e){document.querySelector('#status').textContent='Error: '+e.message}}\n"
"document.querySelector('#add').onclick=()=>{records.push({key:'',held:null,data:null});persist();render()};\n"
"document.querySelector('#clear').onclick=()=>{if(!confirm('Clear all measurements?'))return;records=[];persist();render()};\n"
"document.querySelector('#report').onclick=async()=>{let lines=['PIKO phased key mapping report','Firmware: 10ms scan + 600us per selection; GPIO edge IRQ counters','Shift register: DATA GPIO26, CLOCK GPIO27, LATCH GPIO14; 6 selection bits + factory bit6 high; input columns GPIO32/33/34','Key | Held-state vs baseline; transitions; release check'];records.forEach(r=>{if(r.key.trim())lines.push(r.key+' | '+format(r.data,r.held));});let report=lines.join('\\n');document.querySelector('#output').textContent=report;try{await navigator.clipboard.writeText(report);document.querySelector('#status').textContent='Report copied'}catch(e){document.querySelector('#status').textContent='Copy not available; select text below'}};\n"
"render();\n"
"</script></main></html>\n";
